// tree diameter: longest downward path through each node, combined pairwise
ll best = 0;
ll down(int u, int p) {
    ll m1 = 0, m2 = 0;
    for (int v : adj[u]) {
        if (v == p) continue;
        ll d = down(v, u) + 1;
        if (d > m1) { m2 = m1; m1 = d; } else if (d > m2) m2 = d;
    }
    best = max(best, m1 + m2);
    return m1;
}

