ll go(int pos, int sum, bool tight, bool started) {
    if (pos == (int)S.size()) return started ? 1 : 0;
    if (!tight && memo[pos][sum][started] != -1) return memo[pos][sum][started];

    int hi = tight ? S[pos] - '0' : 9;
    ll res = 0;
    for (int d = 0; d <= hi; d++)
        res += go(pos + 1, sum + d, tight && (d == hi), started || d > 0);

    if (!tight) memo[pos][sum][started] = res;
    return res;
}
