from functools import lru_cache

def count(N):
    S = str(N)
    @lru_cache(maxsize=None)
    def go(pos, sm, tight, started):
        if pos == len(S):
            return 1 if started else 0
        hi = int(S[pos]) if tight else 9
        res = 0
        for d in range(hi + 1):
            res += go(pos + 1, sm + d, tight and d == hi, started or d > 0)
        return res
    r = go(0, 0, True, False)
    go.cache_clear()          # clear between different bounds
    return r

