// extended Euclid: returns g = gcd(a,b), sets x,y with ax + by = g
ll egcd(ll a, ll b, ll &x, ll &y) {
    if (!b) { x = 1; y = 0; return a; }
    ll x1, y1, g = egcd(b, a % b, x1, y1);
    x = y1; y = x1 - (a / b) * y1;
    return g;
}

ll inverse(ll a, ll m) {                  // m need NOT be prime
    ll x, y;
    if (egcd(a, m, x, y) != 1) return -1; // no inverse
    return (x % m + m) % m;
}

